    private static Set<String> superslicerRemoved() {
        Set<String> s = new LinkedHashSet<>();
        return s;
    }

    public static final Map<String, Map<String, String>> RENAMES;
    public static final Map<String, Map<String, Map<String, String>>> VALUES;
    public static final Map<String, Set<String>> REMOVED;
    static {
        Map<String, Map<String, String>> r = new HashMap<>();
        Map<String, Map<String, Map<String, String>>> v = new HashMap<>();
        Map<String, Set<String>> d = new HashMap<>();
        r.put("orca", orcaKeys());
        v.put("orca", orcaValues());
        d.put("orca", orcaRemoved());
        r.put("bambu", bambuKeys());
        v.put("bambu", bambuValues());
        d.put("bambu", bambuRemoved());
        r.put("prusaslicer", prusaslicerKeys());
        v.put("prusaslicer", prusaslicerValues());
        d.put("prusaslicer", prusaslicerRemoved());
        r.put("slic3r", slic3rKeys());
        v.put("slic3r", slic3rValues());
        d.put("slic3r", slic3rRemoved());
        r.put("superslicer", superslicerKeys());
        v.put("superslicer", superslicerValues());
        d.put("superslicer", superslicerRemoved());
        RENAMES = Collections.unmodifiableMap(r);
        VALUES = Collections.unmodifiableMap(v);
        REMOVED = Collections.unmodifiableMap(d);
    }

    public static boolean isRemoved(String dialect, String key) {
        Set<String> s = REMOVED.get(dialect);
        return s != null && s.contains(key);
    }

    public static String rename(String dialect, String key) {
        Map<String, String> m = RENAMES.get(dialect);
        if (m == null) return key;
        String t = m.get(key);
        return t != null ? t : key;
    }

    public static String value(String dialect, String key, String value) {
        Map<String, Map<String, String>> m = VALUES.get(dialect);
        if (m == null) return value;
        Map<String, String> vv = m.get(key);
        if (vv == null) return value;
        String t = vv.get(value.trim());
        return t != null ? t : value;
    }
